'use strict';
(()=>{
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),icon=n=>window.WorkspaceUI?.icon(n)||'';
const root='/api/literature-workspace/';
async function api(path,body){const tourSession=window.LabGuidedTour?.session;let r;try{r=await fetch(root+path,body===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});}catch{throw Error('无法连接文献服务，请检查服务后重试。');}let x;try{x=await r.json();}catch{throw Error('服务返回格式不匹配，请更新项目并重启。');}if(!r.ok)throw Error(x.error||'请求失败。');window.dispatchEvent(new CustomEvent('lab:response',{detail:{project:'D13',session:tourSession,path,body,result:x}}));return x;}
const names={full_text:'提供的原文',abstract:'仅摘要',notes:'阅读摘记',method:'研究方法',finding:'主要发现',limitation:'局限与空白',pending:'待核对',confirmed:'已核对',conflict:'有分歧',stale:'来源已变更',included:'已纳入',excluded:'已排除',undecided:'待定',queued:'等待执行',running:'执行中',succeeded:'已完成',failed:'失败',cancelled:'已取消',interrupted:'执行中断',ready:'可阅读',offline:'离线摘编',single:'单次模型',multi:'分工协作',read:'阅读文献',write:'分节写作',import:'解析文献',approved:'核对通过',rejected:'需修改'};
const name=k=>names[k]||k,badge=(k,label)=>`<span class="status status-${h(k)}">${h(label||name(k))}</span>`,link=(route,label,cls='')=>`<a class="${h(cls)}" href="#${h(route)}">${h(label)}</a>`,date=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—';
const field=(label,key,value='',extra='')=>`<label>${h(label)}<input name="${key}" value="${h(value)}" ${extra}></label>`,area=(label,key,value='',extra='')=>`<label>${h(label)}<textarea aria-label="${h(label)}" name="${key}" ${extra}>${h(value)}</textarea></label>`;
const heading=(title,desc,actions='')=>`<header class="page-heading"><div><h1>${h(title)}</h1><p>${h(desc)}</p></div><div class="actions">${actions}</div></header>`;
const empty=(title,body,actions='')=>`<div class="empty">${icon('book')}<h2>${h(title)}</h2><p>${h(body)}</p>${actions}</div>`,note=(title,body,warning=false)=>`<aside class="note ${warning?'warning':''}"><strong>${h(title)}</strong><p>${h(body)}</p></aside>`;
const table=(heads,rows)=>`<div class="table-scroll"><table><thead><tr>${heads.map(x=>`<th scope="col">${h(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
let state,detail=null,evidence=[],route='',seq=0,dirty=false,saving=false,saveTimer=null,autoPromise=Promise.resolve(),draftLocal=null,polling=false,relations=[],projectAudit=null,sourcePreview=null;
const project=id=>state.projects.find(p=>p.id===id),paper=id=>state.papers.find(p=>p.id===id),selection=(p,id)=>p.selections.find(s=>s.paper===id);
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,4000);}
function error(message){$('#error-message').textContent=message;$('#workspace-error').hidden=false;}
function exportsFor(id,release=false,version=null){return ['markdown','bibtex','json'].map(f=>`<a class="secondary btn small" href="${root}${release?'releases':'drafts'}/${h(id)}/export?format=${f}${version?'&version='+version:''}">${{markdown:'Markdown',bibtex:'BibTeX',json:'证据 JSON'}[f]}${icon('arrow')}</a>`).join('');}
function projectRows(items){return items.length?`<div class="project-list">${items.map((p,i)=>`<article class="project-row"><span class="project-index">${String(i+1).padStart(2,'0')}</span><div><h3>${link('project/'+p.id,p.title)}</h3><p>${h(p.question)}</p></div><span class="counts">${p.selections.filter(s=>s.decision==='included').length} 篇纳入 · ${state.drafts.filter(d=>d.project===p.id).length} 份草案</span></article>`).join('')}</div>`:empty('先确定一个研究问题','围绕具体问题建立专题，再导入、筛选文献。筛选标准与章节提纲会和证据一起保留。',link('new','建立研究专题','btn'));}
function jobRows(items){return items.length?table(['任务','方式 / 状态','时间'],items.map(j=>[link('job/'+j.id,name(j.kind)+' · '+(project(j.project)?.title||'文献导入')),badge(j.mode)+' '+badge(j.status),h(date(j.created))])):empty('暂无执行任务','阅读与写作会分别记录节点结果；失败后可显式重试。');}
function overview(){const latest=state.projects[0],active=state.jobs.filter(j=>['queued','running'].includes(j.status));return heading('文献研读工作台','让论述保留出处，让不同研究的条件和分歧清晰可查。',link('new','建立研究专题','btn'))+`<section class="research-desk"><div class="research-desk-main"><span class="desk-icon">${icon('book')}</span><h2>${latest?'继续：'+h(latest.title):'从一个具体问题开始阅读'}</h2><p>${latest?h(latest.question):'先确定研究范围，再把方法、发现和局限整理到证据中。离线流程可先验证操作，模型写作需逐条核对。'}</p><div class="actions">${latest?link('project/'+latest.id+'?tab=matrix','继续整理证据','btn'):link('new','建立第一个专题','btn')}${link('import','导入文献','btn secondary')}</div></div><aside class="desk-next"><h3>把下一步做清楚</h3><a href="#${latest?'project/'+latest.id+'?tab=compare':'library'}"><strong>对照文献</strong><span>比较方法、发现与局限，保留输入范围。</span></a><a href="#${latest?'project/'+latest.id+'?tab=audit':'guide'}"><strong>检查写作准备</strong><span>找出待核对、过期关系和来源缺口。</span></a><p>${state.papers.length}篇文献 / ${state.projects.length}个专题 / ${active.length}项进行中任务</p></aside></section><div class="section-heading"><h2>研究专题</h2>${link('projects','全部专题')}</div>${projectRows(state.projects)}<div class="section-heading"><h2>最近任务</h2>${link('jobs','全部任务')}</div>${jobRows(state.jobs.slice(0,4))}`;}
function library(q){const query=q.get('q')||'',items=state.papers.filter(p=>(p.title+' '+p.authors+' '+p.doi).toLowerCase().includes(query.toLowerCase()));return heading('文献库','原文、摘要和阅读摘记分别标注。上传修订会保留旧版本。',link('import','导入文献','btn'))+`<form id="filter-form" class="filter-form">${field('搜索标题、作者或 DOI','q',query)}<button type="submit" class="secondary">搜索</button></form>`+(items.length?table(['文献','输入范围','解析状态','版本'],items.map(p=>[`<strong>${link('paper/'+p.id,p.title)}</strong><small>${h(p.authors||'作者待补')} · ${h(p.year||'年份待补')}</small>`,badge(p.scope),badge(p.status),`v${p.current} · ${p.pages} 页`])):empty(query?'没有匹配文献':'尚未导入文献','上传文本型 PDF 或 UTF-8 文本。扫描件请先自行 OCR；不会自动抓取网址。',link('import','导入第一篇文献','btn')));}
function projectForm(p=null){return `<form id="project-form" class="panel" data-id="${h(p?.id||'')}">${field('专题名称','title',p?.title||'','required maxlength="120"')}${area('研究问题','question',p?.question||'','required maxlength="1500" placeholder="例如：检索增强方法如何处理来源冲突？比较哪些条件与指标？"')}<div class="form-grid">${area('纳入标准','inclusion',p?.inclusion||'','maxlength="2000" placeholder="研究对象、方法、年份与来源类型"')}${area('排除标准','exclusion',p?.exclusion||'','maxlength="2000" placeholder="不相关任务、重复版本、缺少原文等"')}</div>${area('章节提纲（每行一章，1–4 章）','outline',p?p.outline.map(s=>s.title).join('\n'):'研究方法\n主要发现\n局限与研究空白','required')}<label class="check"><input type="checkbox" name="outline_confirmed" ${p?.outline_confirmed?'checked':''}>我已确认章节范围，允许进入写作阶段</label><button type="submit">${p?'保存专题与提纲':'建立专题'}</button><p class="form-message" role="status"></p></form>`;}
function newProject(){return heading('建立研究专题','用可以回答的问题限定范围。稍后可在专题中修订标准与提纲。')+`<div class="form-layout">${projectForm()}<aside>${note('从问题开始','避免以“人工智能研究综述”这样的宽泛主题起步。明确对象、比较维度与范围后，再筛选文献。')}<ol class="step-list"><li><div><strong>专题范围</strong>每个专题最多纳入 6 篇文献，适合先验证一轮完整流程。</div></li><li><div><strong>有条件的比较</strong>保留数据集、实验设定与评价指标，不直接拼接不同条件的结论。</div></li><li><div><strong>可修改的提纲</strong>先组织方法、发现与限制；改变提纲后，旧草案会显示来源变更。</div></li></ol></aside></div>`;}
function importPage(q){const id=q.get('paper'),p=paper(id);if(id&&!p)return heading('文献已不在当前库中','可从旧草案读取被冻结的来源，重新导入请返回文献库。')+link('library','返回文献库','btn');return heading(p?'上传文献修订':'导入文献','文件只保存在当前服务的数据目录中；模型模式由你在任务中另行选择。')+`<div class="form-layout"><form id="import-form" class="panel" data-paper="${h(id||'')}">${p?note('修订 v'+p.current,'解析成功后才切换当前版本。旧证据保留原版本定位，并显示过期。'):''}${field('文献标题','title',p?.title||'','required maxlength="300"')}${field('作者','authors',p?.authors||'','maxlength="500"')}<div class="form-grid">${field('发表年份','year',p?.year||'','type="number" min="1900" max="2100"')}${field('DOI（可选）','doi',p?.doi||'','maxlength="200"')}</div>${field('原文链接（仅记录，不抓取）','url',p?.url||'','type="url" maxlength="1000"')}<label>输入范围<select name="scope" aria-label="输入范围">${['full_text','abstract','notes'].map(k=>`<option value="${k}" ${p?.scope===k?'selected':''}>${name(k)}</option>`).join('')}</select></label><label>文件（PDF / TXT / Markdown，最多 8 MiB）<input type="file" name="file" accept=".pdf,.txt,.md"></label>${area('或粘贴 UTF-8 文本','text','','maxlength="300000" placeholder="有文件时优先读取文件。请提供你有权使用的文献文本。"')}<div class="actions"><button type="submit">${p?'导入新版本':'开始导入'}</button><button type="button" id="fill-sample" class="secondary">填入教学文本</button></div><p class="form-message" role="status"></p></form><aside><ol class="step-list"><li><div><strong>记录来源</strong>补齐标题、作者和年份，参考文献将使用这些元数据。</div></li><li><div><strong>如实标明范围</strong>只有摘要或阅读摘记时，不应按阅读全文解释结果。</div></li><li><div><strong>解析后核对</strong>PDF 文本提取可能丢失表格与公式，请回到原文件检查。</div></li></ol>${note('无需模型即可使用','离线流程提供摘录与编排，不执行语义归纳。教学文本为虚构材料，不属于真实论文。')}</aside></div>`;}
function pageText(p,location=null){let content=h(p.text);if(location&&location.page===p.page){const chars=Array.from(p.text);content=h(chars.slice(0,location.start).join(''))+'<mark id="source-highlight">'+h(chars.slice(location.start,location.end).join(''))+'</mark>'+h(chars.slice(location.end).join(''));}return `<article class="paper-page"><div class="page-label">提取文本 · 第 ${p.page} 页 · 字符位置从 0 计数</div><div class="source-text" data-page="${p.page}">${content}</div></article>`;}
function paperView(doc,q){const v=doc.version,m=v.metadata,pr=project(q.get('project')),pg=Number(q.get('page')||v.pages[0]?.page||1),current=v.pages.find(p=>p.page===pg)||v.pages[0];let loc=null;if(q.has('start')&&q.has('end'))loc={page:pg,start:Number(q.get('start')),end:Number(q.get('end'))};const base='paper/'+doc.paper.id+'?version='+v.number+(pr?'&project='+pr.id:'');return heading(m.title,m.authors+' · '+(m.year||'年份待补'),`<a class="btn secondary small" href="${root}papers/${h(doc.paper.id)}/file?version=${v.number}">下载原文件</a>${doc.paper.active?link('import?paper='+doc.paper.id,'上传修订','secondary btn small'):''}<button id="archive-paper" class="text-button small" ${doc.paper.active?'':'disabled'}>移出文献库</button>`)+`<div class="actions">${badge(m.scope)}${badge(v.status)}<span class="muted">v${v.number} ${doc.paper.current===v.number?'· 当前版本':'· 历史版本'}</span></div>${m.scope!=='full_text'?note('输入范围：'+name(m.scope),'本材料不是论文全文，摘录与综述只能依据当前输入范围。'):''}<div class="matrix-toolbar"><div class="actions">${v.pages.map(p=>link(base+'&page='+p.page,'第 '+p.page+' 页',p.page===pg?'btn small':'secondary btn small')).join('')}</div><label>文献版本<select id="paper-version" aria-label="文献版本">${doc.versions.map(r=>`<option value="${r.number}" ${r.number===v.number?'selected':''}>v${r.number} · ${name(r.status)}</option>`).join('')}</select></label></div><div class="reader-grid"><section>${current?pageText(current,loc):note('尚无可阅读文本',v.error||'正在解析，可在任务列表查看进度。')}</section><aside class="reader-side"><div class="panel"><h2>阅读与摘录</h2><dl class="meta"><dt>文献版本</dt><dd>v${v.number}</dd><dt>输入范围</dt><dd>${h(name(m.scope))}</dd><dt>文件</dt><dd>${h(v.filename)}</dd><dt>DOI</dt><dd>${h(m.doi||'待补')}</dd></dl><label>摘录到研究专题<select id="reader-project" aria-label="摘录到研究专题"><option value="">请选择专题</option>${state.projects.map(p=>`<option value="${h(p.id)}" ${p.id===pr?.id?'selected':''}>${h(p.title)}</option>`).join('')}</select></label>${pr?(selection(pr,doc.paper.id)?.decision==='included'?`<p class="muted">选中左侧原文后点击“摘录选中文本”，也可手工粘贴并核对位置。</p><button id="quote-selection" class="secondary" data-project="${h(pr.id)}" data-paper="${h(doc.paper.id)}" data-version="${v.number}" data-page="${current?.page||1}">摘录选中文本</button>`:note('尚未纳入此专题','请先在专题筛选中记录纳入理由。')):''}${pr?link('project/'+pr.id+'?tab=matrix','回到证据矩阵 →'):''}</div>${note('关于逐字核查','系统校验片段、页码与字符位置，不判断一段引文是否支持某个结论。摘要范围、实验条件与因果关系仍需人工阅读。')}</aside></div>`;}
function modeChoice(kind){return `<form class="mode-choice" data-generate="${kind}"><label><span class="sr-only">${kind==='read'?'阅读方式':'写作方式'}</span><select name="mode"><option value="offline">离线${kind==='read'?'摘录':'编排'} · 不调用模型</option><option value="single" ${state.capabilities.llm?'':'disabled'}>单次模型 · 1 次调用</option><option value="multi" ${state.capabilities.llm?'':'disabled'}>分工协作 · 按${kind==='read'?'文献':'章节'}调用</option></select></label><button type="submit">${kind==='read'?'建立阅读任务':'生成章节草案'}</button></form>`;}
function projectLink(p,tab,changes={}){return 'project/'+p.id+'?'+new URLSearchParams({tab,...changes});}
function auditExports(p){return ['json','markdown','csv'].map(f=>`<a class="btn secondary small" href="${root}projects/${h(p.id)}/audit/export?format=${f}">导出${{json:'证据 JSON',markdown:'核对记录',csv:'证据 CSV'}[f]}</a>`).join('');}
function evidenceFilters(p,q){return `<form id="evidence-filter" class="evidence-filter" data-project="${h(p.id)}"><label>搜索引文或说明<input name="evidence_q" value="${h(q.get('evidence_q')||'')}" placeholder="关键词、条件或研究对象"></label><label>核对状态<select name="status"><option value="all">全部状态</option>${['pending','confirmed','conflict','stale'].map(k=>`<option value="${k}" ${q.get('status')===k?'selected':''}>${name(k)}</option>`).join('')}</select></label><label>来源文献<select name="paper"><option value="all">全部文献</option>${p.selections.filter(s=>s.decision==='included').map(s=>`<option value="${h(s.paper)}" ${q.get('paper')===s.paper?'selected':''}>${h(paper(s.paper)?.title||s.paper)}</option>`).join('')}</select></label><button type="submit" class="secondary">筛选证据</button>${link(projectLink(p,'matrix'),'清除筛选','text-button')}</form>`;}
function evidenceCard(p,e){return `<article class="evidence-card" data-evidence="${h(e.id)}"><header><small>${h(e.id.slice(-6))}</small>${badge(e.stale?'stale':e.status)}</header><a class="citation" href="#paper/${h(e.paper)}?project=${h(p.id)}&version=${e.version}&page=${e.page}&start=${e.start}&end=${e.end}">${h(paper(e.paper)?.title||e.paper)} / v${e.version} / p.${e.page}</a><blockquote>${h(e.quote)}</blockquote><p>${h(e.summary)}</p>${e.actor?`<small>${h(e.actor)} / ${h(e.comment)}</small>`:''}<footer>${link(projectLink(p,'matrix',{evidence:e.id}),'并排核对','btn secondary small')}<button class="text-button" data-cite="${h(e.id)}">对照原文</button><button class="text-button" data-edit-evidence="${h(e.id)}">编辑</button><button class="text-button" data-review-evidence="${h(e.id)}" ${e.stale?'disabled':''}>核对</button><button class="text-button" data-delete-evidence="${h(e.id)}">移除</button></footer></article>`;}
function sourceInspector(p,e){
 if(!e||!sourcePreview)return '';
 const pg=sourcePreview.version.pages.find(pg=>pg.page===e.page),chars=Array.from(pg?.text||''),start=Math.max(0,e.start-130),end=Math.min(chars.length,e.end+180);
 return `<aside class="evidence-inspector"><div class="inspector-heading"><h2>原文核对</h2>${link(projectLink(p,'matrix'),'关闭','text-button')}</div><p>${h(sourcePreview.version.metadata.title)}</p><div class="actions">${badge(sourcePreview.version.metadata.scope)}${badge(e.stale?'stale':e.status)}</div><small>v${e.version} / p.${e.page} / 字符 ${e.start}–${e.end}</small><div class="inspector-source">${start?'…':''}${h(chars.slice(start,e.start).join(''))}<mark>${h(chars.slice(e.start,e.end).join(''))}</mark>${h(chars.slice(e.end,end).join(''))}${end<chars.length?'…':''}</div><h3>证据含义与条件</h3><p>${h(e.summary)}</p><div class="actions"><button class="secondary small" data-review-evidence="${h(e.id)}" ${e.stale?'disabled':''}>核对</button><button class="text-button" data-edit-evidence="${h(e.id)}">编辑</button></div>${link('paper/'+e.paper+'?project='+p.id+'&version='+e.version+'&page='+e.page+'&start='+e.start+'&end='+e.end,'打开完整原文','btn secondary small')}<p class="muted">高亮只验证逐字位置；是否支持结论，仍需阅读上下文。</p></aside>`;
}
function matrixReview(p,q){
 const query=(q.get('evidence_q')||'').trim().toLowerCase(),filter=q.get('status')||'all',pid=q.get('paper')||'all';
 const rows=evidence.filter(e=>(pid==='all'||e.paper===pid)&&(filter==='all'||(filter==='stale'?e.stale:!e.stale&&e.status===filter))&&(!query||(e.quote+' '+e.summary).toLowerCase().includes(query))),selected=evidence.find(e=>e.id===q.get('evidence'));
 return `<div class="matrix-toolbar"><div><strong>${evidence.filter(e=>e.status==='confirmed'&&!e.stale).length}</strong> / ${evidence.length}条已核对</div><div class="actions">${link(projectLink(p,'compare'),'按文献对照','btn secondary small')}<button id="add-evidence" class="secondary small" ${p.selections.some(s=>s.decision==='included')?'':'disabled'}>手工摘录 +</button></div></div>${modeChoice('read')}${evidenceFilters(p,q)}${note('先核对，再写作','离线摘录不进行语义综合。请编辑类别和适用条件；模型结果也需人工核对。')}<div class="evidence-review-layout ${selected?'with-inspector':''}"><section>${rows.length?`<div class="matrix-grid">${['method','finding','limitation'].map(f=>`<section class="matrix-column"><h2>${name(f)}<span>${rows.filter(e=>e.field===f).length}</span></h2>${rows.filter(e=>e.field===f).map(e=>evidenceCard(p,e)).join('')||'<p class="muted">当前筛选下无此类证据</p>'}</section>`).join('')}</div>`:empty(evidence.length?'没有匹配的证据':'将原文整理为可核对的证据',evidence.length?'调整关键词、状态或文献筛选后重试。':'可手工摘录，也可先建立阅读任务。引文必须连续匹配原文。')}</section>${sourceInspector(p,selected)}</div>`;
}
function paperComparison(p){const rows=p.selections.filter(s=>s.decision==='included');return `<div class="matrix-toolbar"><p class="muted">按文献保留方法、发现与局限，避免把不同条件的结果直接拼接。</p><div class="actions">${auditExports(p)}</div></div>${rows.length?table(['文献 / 输入范围','研究方法','主要发现','局限与空白'],rows.map(s=>{const doc=paper(s.paper),cells=['method','finding','limitation'].map(f=>{const es=evidence.filter(e=>e.paper===s.paper&&e.field===f);return es.map(e=>`<article class="compare-evidence">${badge(e.stale?'stale':e.status)}<p>${h(e.summary)}</p><blockquote>${h(e.quote)}</blockquote>${link(projectLink(p,'matrix',{evidence:e.id}),'核对原文')}</article>`).join('')||'<span class="muted">尚未记录；请判断是否适用。</span>';});return [`<strong>${h(doc?.title||s.paper)}</strong>${badge(doc?.scope||'notes')}<small>当前 v${doc?.current||'—'}</small>`,...cells];})):empty('尚未纳入文献','先到文献筛选记录纳入理由。')}`;}
function relationView(p){return `<div class="matrix-toolbar"><p class="muted">记录两条证据在什么条件下支持、存在分歧或互为补充；关系由人判断。</p><button id="new-relation" ${evidence.filter(e=>!e.stale&&e.status==='confirmed').length<2?'disabled':''}>记录证据关系</button></div>${relations.length?relations.map(r=>{const left=evidence.find(e=>e.id===r.left),right=evidence.find(e=>e.id===r.right);return `<article class="relation-row"><div class="relation-title"><h2>${h({supports:'相互支持',contrasts:'存在分歧',complements:'互为补充'}[r.kind])}</h2>${badge(r.stale?'stale':'confirmed',r.stale?'证据已变化':'已记录关系')}</div><div class="relation-endpoints">${[left,right].map((e,i)=>`<div><strong>${h(paper(e?.paper)?.title||'证据已移除')}</strong><blockquote>${h(e?.quote||'原证据已移除，请删除或重新建立关系。')}</blockquote>${e?link(projectLink(p,'matrix',{evidence:e.id}),'核对 '+e.id.slice(-6)):''}</div>`).join('')}</div><p>${h(r.note)}</p><footer><small>${h(r.actor)} / ${h(date(r.updated))} / 修订 ${r.revision}</small><div class="actions"><button class="secondary small" data-edit-relation="${h(r.id)}">修改或重新核对</button><button class="text-button" data-delete-relation="${h(r.id)}">移除关系</button></div></footer><details><summary>查看关系修订记录</summary>${r.history.map(x=>`<p>修订 ${x.revision} / ${h(x.actor)} / ${h(date(x.updated))}<br>${h(x.note)}</p>`).join('')}</details></article>`;}).join(''):empty('还没有证据关系','先核对两条证据，再记录条件差异与联系。新增或修改关系会使旧写作草案显示来源变化。')}`;}
function auditView(p){const a=projectAudit;if(!a)return empty('检查结果尚未读取','请重新打开专题。');return `<div class="audit-verdict ${a.ready_for_writing?'ready':'needs-work'}">${icon(a.ready_for_writing?'check':'info')}<div><h2>${a.ready_for_writing?'结构已就绪，可以进入写作':'先处理这些问题，再开始写作'}</h2><p>${a.blocking.length}项阻断 / ${a.warnings.length}项阅读提醒。此检查不评判论文或论述质量。</p></div>${link(projectLink(p,a.ready_for_writing?'drafts':'matrix'),a.ready_for_writing?'进入章节草案':'处理证据','btn secondary')}</div><div class="actions">${auditExports(p)}</div><section class="audit-issues"><h2>需要处理</h2>${a.blocking.length?a.blocking.map(i=>`<article><span class="issue-dot"></span><div><strong>${h(i.message)}</strong><p>${h(paper(i.paper_id||evidence.find(e=>e.id===i.evidence_id)?.paper)?.title||(i.code==='relation'?'两条证据的关联':'专题设置'))}</p></div>${link(projectLink(p,i.code==='outline'?'outline':i.code==='relation'?'relations':i.code==='no_papers'?'screen':'matrix',i.evidence_id?{evidence:i.evidence_id}:{}),'去处理','btn secondary small')}</article>`).join(''):'<p class="muted">没有阻断项。仍需人工判断引用的语义和研究条件。</p>'}</section><section class="section"><h2>逐篇证据覆盖</h2>${table(['文献','有效 / 总证据','方法','发现','局限'],a.papers.map(r=>[h(r.title),r.confirmed_count+' / '+r.evidence_count,...['method','finding','limitation'].map(f=>r.fields[f].length||'<span class="muted">未记录</span>')]))}</section><section class="section"><h2>阅读与范围提醒</h2>${a.warnings.length?`<ul class="audit-warnings">${a.warnings.map(i=>`<li><strong>${h(paper(i.paper_id)?.title||'专题')}</strong><p>${h(i.message)}</p></li>`).join('')}</ul>`:'<p class="muted">暂无结构性提醒，仍不代表内容质量已通过。</p>'}</section><details><summary>核对上下文指纹</summary><code>${h(a.context_fingerprint)}</code></details>`;}
function showRelationForm(id){
 const r=relations.find(r=>r.id===id),items=evidence.filter(e=>!e.stale&&e.status==='confirmed');
 if(items.length<2)throw Error('请先核对至少两条有效证据。');
 const options=selected=>items.map(e=>`<option value="${h(e.id)}" ${e.id===selected?'selected':''}>${h(paper(e.paper)?.title||e.paper)} / ${h(e.summary.slice(0,55))}</option>`).join('');
 openDialog(r?'重新核对证据关系':'记录证据关系',`<form id="relation-form" data-id="${h(r?.id||'')}" data-revision="${r?.revision||0}"><label>第一条证据<select name="left" aria-label="第一条证据">${options(r?.left||items[0].id)}</select></label><label>第二条证据<select name="right" aria-label="第二条证据">${options(r?.right||items[1].id)}</select></label><label>证据之间的关系<select name="kind" aria-label="证据之间的关系">${[['supports','相互支持'],['contrasts','存在分歧'],['complements','互为补充']].map(([k,l])=>`<option value="${k}" ${r?.kind===k?'selected':''}>${l}</option>`).join('')}</select></label>${area('关系说明与条件差异','note',r?.note||'','required maxlength="2000" placeholder="说明任务、数据、假设或评价条件是否一致。"')}${field('记录人','actor',r?.actor||'','required maxlength="80"')}<p class="muted">保存会固定当前证据修订；后续证据变化需重新核对关系。</p><button type="submit">保存证据关系</button>${formFinish()}</form>`);
}

function projectView(p,q){const tab=q.get('tab')||'screen',selected=p.selections.filter(s=>s.decision==='included'),ready=evidence.filter(e=>e.status==='confirmed'&&!e.stale),ds=state.drafts.filter(d=>d.project===p.id);let content='';if(tab==='screen')content=`${note('筛选记录会影响综述范围','每篇文献单独保存纳入、排除或待定及理由。未纳入的文献不会进入阅读任务。')}<div class="matrix-toolbar"><span class="muted">${state.papers.length} 篇入库 · ${selected.length} 篇纳入（最多 6 篇）</span>${link('import','导入文献 +')}</div>`+(state.papers.length?table(['文献 / 输入范围','筛选记录','操作'],state.papers.map(doc=>{const s=selection(p,doc.id);return [`<strong>${link('paper/'+doc.id+'?project='+p.id,doc.title)}</strong><small>${h(doc.authors||'作者待补')} · ${h(doc.year||'年份待补')}</small>${badge(doc.scope)}`,`${badge(s?.decision||'undecided')}<small>${h(s?.reason||'尚无筛选理由')}</small>`,`<button class="secondary small" data-screen="${h(doc.id)}" ${doc.status==='ready'?'':'disabled'}>记录筛选</button>`];})):empty('先导入文献','导入实际文本后即可筛选并建立证据。',link('import','导入文献','btn')));
else if(tab==='matrix')content=matrixReview(p,q);
else if(tab==='compare')content=paperComparison(p);
else if(tab==='relations')content=relationView(p);
else if(tab==='audit')content=auditView(p);
else if(tab==='outline')content=`<div class="form-layout">${projectForm(p)}<aside>${note('提纲属于来源快照','研究问题、筛选或证据发生变化后，已有草案显示过期。可导出旧结果，按当前输入新建写作任务。')}${note('建议的章节结构','方法如何分类？发现在哪些条件下成立？有哪些冲突与研究空白？使用明确的问题组织内容，避免论文摘要的简单堆叠。')}</aside></div>`;
else content=`<div class="matrix-toolbar"><p class="muted">提纲${p.outline_confirmed?'已确认':'待确认'} · ${ready.length} 条有效证据</p>${modeChoice('write')}</div>${note('生成前检查','提纲需已确认；每篇纳入文献至少有一条已核对证据，矩阵不能存在待核对、冲突或过期项。离线输出仅作证据编排。')}${ds.length?table(['草案','版本','创建时间'],ds.map(d=>[link('draft/'+d.id,p.title+' · 章节草案'),`v${d.current}${d.draft_revision?' · 有草稿记录':''}`,h(date(d.created))])):empty('还没有章节草案','完成证据核对与提纲确认后，在这里生成并进入章节编辑。',link('project/'+p.id+'?tab=matrix','整理证据 →','secondary btn'))}`;
return heading(p.title,p.question,link('library','打开文献库','secondary btn small'))+`<div class="workflow-strip"><div><small>01 / 范围</small><strong>${selected.length} 篇纳入</strong><p>筛选理由与范围</p></div><div><small>02 / 证据</small><strong>${ready.length} 条已核对</strong><p>原文位置与解释</p></div><div><small>03 / 提纲</small><strong>${p.outline_confirmed?'已确认':'尚未确认'}</strong><p>${p.outline.length} 个章节</p></div><div><small>04 / 写作</small><strong>${ds.length} 份草案</strong><p>逐条审核与发布</p></div></div><nav class="tabs" aria-label="专题工作流程">${[['screen','文献筛选'],['matrix','证据矩阵'],['compare','文献对照'],['relations','证据关系'],['audit','写作前检查'],['outline','问题与提纲'],['drafts','章节草案']].map(([k,l])=>`<a href="#project/${h(p.id)}?tab=${k}" ${k===tab?'aria-current="page"':''}>${l}</a>`).join('')}</nav>${content}`;}
function draftView(d,q){const sectionId=q.get('section')||d.sections[0].id,mode=q.get('mode')||'edit',historical=d.version!==d.current,sections=d.draft&&!historical?d.draft:d.sections,s=sections.find(s=>s.id===sectionId)||sections[0],edit=mode==='edit'&&!historical&&!d.stale,last=Object.fromEntries(d.reviews.map(r=>[r.claim,r.decision])),pr=d.context.project;draftLocal=structuredClone(sections);let content=`<section class="manuscript"><p class="eyebrow">${h(s.id)} / ${h(pr.title)}</p><h2>${h(s.title)}</h2>`;
if(mode==='review')content+=`<form id="claim-review-form"><div class="actions"><button id="select-claims" type="button" class="secondary small">选择本章全部论述</button><span class="muted">请逐条核对引文与论述关系</span></div>${s.claims.map(c=>`<article class="claim"><header><label class="check"><input type="checkbox" name="claim_ids" value="${h(c.id)}" ${d.stale||historical||d.draft?'disabled':''}>${h(c.id)}</label>${badge(last[c.id]||'pending')}</header><p>${h(c.text)}</p><div class="evidence-links">${c.evidence_ids.map(id=>`<button type="button" class="cite" data-cite="${h(id)}">${h(id.slice(-6))} · 查看原文</button>`).join('')}</div></article>`).join('')}<div class="form-grid">${field('核对人','actor','','required maxlength="80"')}<label>结论<select name="decision" aria-label="结论"><option value="approved">核对通过</option><option value="rejected">需修改</option></select></label></div>${area('核对依据','comment','','required maxlength="2000" placeholder="说明范围、实验条件、引用是否支持论述及待补问题。"')}<button type="submit" ${d.stale||historical||d.draft?'disabled':''}>保存所选论述核对记录</button><p class="form-message" role="status"></p></form>`;
else content+=`<form id="draft-form">${s.claims.map(c=>`<article class="claim" data-claim="${h(c.id)}"><header><span>${h(c.id)}</span><span>${c.evidence_ids.length} 条来源</span></header>${edit?area('论述文本','text-'+c.id,c.text,'required maxlength="3000" data-claim-text="'+c.id+'"'):`<p>${h(c.text)}</p>`}${edit?`<label>引用证据（可多选，1–4 条）<select multiple data-claim-evidence="${h(c.id)}" aria-label="${h(c.id)} 引用证据">${d.context.evidence.map(e=>`<option value="${h(e.id)}" ${c.evidence_ids.includes(e.id)?'selected':''}>${h(e.id.slice(-6))} · ${h(e.summary.slice(0,65))}</option>`).join('')}</select></label>`:''}<div class="evidence-links">${c.evidence_ids.map(id=>`<button type="button" class="cite" data-cite="${h(id)}">${h(id.slice(-6))} · 对照原文</button>`).join('')}</div></article>`).join('')}${edit?`<div class="savebar"><span id="save-state">${d.draft?'已保存草稿，尚未提交版本':'编辑后自动保存草稿'}</span><div class="actions"><button type="submit" class="secondary small">保存草稿</button><button type="button" id="commit-draft">提交新版本</button></div></div>`:''}<p class="form-message" role="status"></p></form>`;
content+='</section>';const all=d.sections.flatMap(s=>s.claims),approved=all.filter(c=>last[c.id]==='approved').length;
return heading(pr.title+' · 章节草案',`基于固定来源快照 · 已提交 v${d.version} · ${approved} / ${all.length} 条核对通过`,exportsFor(d.id,false,d.version))+`${d.stale?note('来源已变化','旧草案可阅读和导出，不能继续审核或发布。请回到专题检查证据，按当前输入重新生成。',true):''}${historical?note('正在查看历史版本','此版本只读，核对记录与当前版本分别保存。'):''}${d.draft?note('有尚未提交的草稿','自动保存不改变已提交版本。提交后需针对新版本重新核对；导出始终使用已提交版本。'):''}<div class="matrix-toolbar"><div class="actions">${link('project/'+d.project+'?tab=drafts','← 返回专题')}<label>草案版本<select id="draft-version" aria-label="草案版本">${d.versions.map(v=>`<option value="${v.number}" ${v.number===d.version?'selected':''}>v${v.number}</option>`).join('')}</select></label></div><div class="actions">${d.draft&&!historical?'<button id="discard-draft" class="text-button">放弃已保存草稿</button>':''}<button id="publish-draft" ${approved===all.length&&!d.stale&&!d.draft&&!historical?'':'disabled'}>发布审核快照</button></div></div><nav class="tabs" aria-label="章节编辑模式">${[['edit','编辑章节'],['review','引用核对']].map(([k,l])=>`<a href="#draft/${h(d.id)}?version=${d.version}&section=${h(s.id)}&mode=${k}" ${mode===k?'aria-current="page"':''}>${l}</a>`).join('')}</nav><div class="draft-layout"><aside class="outline-nav"><p>章节目录</p>${sections.map(sec=>`<a href="#draft/${h(d.id)}?version=${d.version}&section=${h(sec.id)}&mode=${h(mode)}" ${sec.id===s.id?'aria-current="page"':''}>${h(sec.title)}</a>`).join('')}</aside>${content}</div>${d.reviews.length?`<section class="review-list"><div class="section-heading"><h2>本版本核对记录</h2><span>${d.reviews.length} 条</span></div>${d.reviews.map(r=>`<article>${badge(r.decision)} ${h(r.claim)} · ${h(r.actor)} · ${h(date(r.created))}<p>${h(r.comment)}</p></article>`).join('')}</section>`:''}`;}
function jobsView(){return heading('任务记录','阅读与写作分阶段执行，节点输出保留在当前工作区中。')+jobRows(state.jobs);}
function jobView(j){return heading(name(j.kind),name(j.mode)+' · '+j.id,`<button id="refresh" class="secondary small">刷新状态</button>${['queued','running'].includes(j.status)?'<button data-job-action="cancel" class="secondary small">停止任务</button>':''}${['failed','interrupted','cancelled'].includes(j.status)?'<button data-job-action="retry">重试未完成节点</button>':''}`)+`<div class="actions">${badge(j.status)}<span class="muted">${h(date(j.created))}</span></div>${j.error?note('任务未提交结果',j.error,true):''}${j.result.draft_id?note('章节草案已保存','请进入编辑区核对论述与引用。')+link('draft/'+j.result.draft_id,'打开章节草案 →','btn'):''}${j.result.evidence_ids?note('阅读结果已加入矩阵',j.result.evidence_ids.length+' 条证据均为待核对状态。')+link('project/'+j.project+'?tab=matrix','核对阅读证据 →','btn'):''}${j.kind==='import'&&j.status==='succeeded'?link('paper/'+j.payload.paper,'打开文献 →','btn'):''}<div class="section-heading"><h2>执行节点</h2><span>已完成节点可复用 · 不自动重试付费调用</span></div>${j.nodes.length?`<div class="node-list">${j.nodes.map((n,i)=>`<article class="node"><span class="node-number">${String(i+1).padStart(2,'0')}</span><div><h3>${h(n.key)}</h3><p>${h(n.error||'')}${n.reused_from?'复用自 '+h(n.reused_from):''}</p>${n.result?`<details><summary>查看节点输出</summary><pre>${h(JSON.stringify(n.result,null,2))}</pre></details>`:''}</div>${badge(n.status)}</article>`).join('')}</div>`:empty('任务等待执行','服务端队列会依次领取任务，页面关闭不取消执行。')}${note('调用边界',j.mode==='offline'?'本任务不调用模型。离线摘录不执行语义分析。':`模型：${j.model||'未记录'}。阅读最多 6 个文献节点，写作最多 4 个章节节点；阅读并发 3、写作并发 2。每次调用超时 45 秒。当前供应商未提供可用计费记录，不显示估算 token 或费用。`)}`;}
function releasesView(){return heading('已发布快照','发布固定章节、来源版本与人工核对记录。后续编辑不会改变已有快照。')+(state.releases.length?state.releases.map(r=>`<article class="release-row"><div><h3>${h(r.id)}</h3><p>草案 ${h(r.draft)} · v${r.version} · ${h(date(r.created))}</p></div><div class="actions">${exportsFor(r.id,true)}</div></article>`).join(''):empty('尚未发布综述','提交草案版本并核对全部论述后，可发布一份可导出的审核快照。'));}
const chapters=[['requirements','需求分析'],['architecture','架构设计'],['development','代码开发'],['workflow','任务流程'],['evaluation','成果评估'],['boundary','部署与边界']];
function guide(){return heading('项目指南','从开题到验收：围绕可追溯的文献证据建立综述，而不仅是生成一篇文本。')+`<section class="panel guide-extension"><h2>把不同文献的条件与分歧讲清楚</h2><p>证据矩阵可按关键词、来源和状态筛选。点击“并排核对”在同页查看高亮原文，或进入“文献对照”按方法、发现和局限比较。对两条有效且已核对证据，可以记录支持、分歧或补充关系及条件说明。</p><p>修改证据或关系会使旧草案显示来源变化；关系过期后需重新核对或移除，才能写作。“写作前检查”区分阻断项与阅读提醒，类别为空、摘要输入只是提醒，不能作为生成更多内容的理由。检查就绪不等于语义正确。证据、关系和检查记录支持JSON/Markdown导出，CSV用于表格核查。</p></section>`+`<div class="guide-layout"><nav class="guide-nav" aria-label="指南目录">${chapters.map(([id,title],i)=>`<a href="#guide?chapter=${id}">${String(i+1).padStart(2,'0')} ${title}</a>`).join('')}</nav><article class="guide-content"><section id="requirements"><p class="eyebrow">01 / 问题与范围</p><h2>需求分析：综述为什么需要证据工作区</h2><p>研究者需要比较多篇论文的方法、适用条件与局限。只返回一段生成文本，很难区分原文结论、作者归纳与模型补写。D13 将任务拆成文献筛选、阅读证据、章节写作和引用核对四个阶段。</p><h3>输入、输出与角色</h3><p>输入是文本型 PDF 或 UTF-8 文本、研究问题、纳入/排除标准和提纲。输出是带证据映射的章节、版本快照与 Markdown/BibTeX/JSON。阅读者检查来源，章节作者组织论述，核对者确认引用与结论是否匹配。当前不提供角色权限或身份认证。</p>${note('开题范围示例','围绕“检索增强方法如何处理来源冲突”设定专题。比较方法、数据集和冲突处理证据；先用 2–6 篇文献走通全流程，再扩展样本。')}</section><section id="architecture"><p class="eyebrow">02 / 数据与执行</p><h2>架构设计：把原文、证据与论述连接起来</h2><div class="diagram-scroll" tabindex="0" role="region" aria-label="架构图，窄屏可横向滚动"><svg class="architecture" viewBox="0 0 700 340" role="img" aria-label="D13 架构：文献解析与版本进入证据矩阵，章节写作后经人工核对发布；各阶段持久化到 SQLite"><defs><marker id="arrowhead" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0 L7 3.5 L0 7" fill="#57738c"/></marker></defs><g font-family="system-ui,sans-serif" fill="#223b53"><rect x="32" y="35" width="190" height="80" rx="5" fill="#fffefa" stroke="#b9c7d1"/><text x="49" y="65" font-size="15">文献 / 版本</text><text x="49" y="90" font-size="12" fill="#667989">范围 · 页码 · 原文</text><rect x="265" y="35" width="190" height="80" rx="5" fill="#fffefa" stroke="#b9c7d1"/><text x="282" y="65" font-size="15">阅读 / 证据矩阵</text><text x="282" y="90" font-size="12" fill="#667989">逐字定位 · 人工核对</text><rect x="497" y="35" width="170" height="80" rx="5" fill="#fffefa" stroke="#b9c7d1"/><text x="512" y="65" font-size="15">分节写作</text><text x="512" y="90" font-size="12" fill="#667989">论述 → 证据 ID</text><rect x="497" y="160" width="170" height="75" rx="5" fill="#dbe5ee" stroke="#9eafbe"/><text x="512" y="191" font-size="15">审核 / 发布</text><text x="512" y="215" font-size="12">版本快照 · 三种导出</text><rect x="32" y="160" width="423" height="75" rx="5" fill="#dde5df" stroke="#aebdb2"/><text x="49" y="191" font-size="15">SQLite / 数据与节点检查点</text><text x="49" y="215" font-size="12">输入指纹 · 乐观锁 · 显式重试 · 重启恢复</text></g><g stroke="#57738c" stroke-width="1.5" fill="none" marker-end="url(#arrowhead)"><path d="M223 75H257"/><path d="M456 75H488"/><path d="M582 116V151"/><path d="M128 116V151"/><path d="M360 116V151"/><path d="M489 198H463"/></g><text x="32" y="286" fill="#607487" font-family="system-ui,sans-serif" font-size="13">阅读并发 ≤3 · 写作并发 ≤2 · 引用检查使用确定性规则</text><text x="32" y="312" fill="#607487" font-family="system-ui,sans-serif" font-size="12">原文变更 → 证据过期 → 重新摘录 / 生成，不覆盖旧快照</text></svg></div><p>文献原文件与解析页保存为不可变版本；证据记录文献版本、页码、起止字符和引文；草案冻结专题与证据上下文。任务在后台执行，模型模式区分单次调用与分工协作。失败任务保留成功节点，仅在输入指纹与模型配置一致时允许复用。</p></section><section id="development"><p class="eyebrow">03 / 实现路径</p><h2>代码开发：先让每一步可验证</h2><ol><li><strong>导入与版本：</strong><code>shared/literature_workspace.py</code> 校验文件、元数据与范围，后台调用有资源限制的 PDF 解析器，成功后切换当前版本。</li><li><strong>领域与接口：</strong>SQLite 保存专题、筛选、证据、任务、草案和快照。<code>server.py</code> 暴露同源 JSON 接口；修改使用版本号或 revision 防止覆盖。</li><li><strong>分工执行：</strong>阅读节点按文献生成带定位证据；章节节点按提纲写作。<code>shared/model_client.py</code> 负责可选模型 API。模型输入只按任务需要发送，不自动搜索或追加外部论文。</li><li><strong>前端交互：</strong><code>demos/06-literature/workspace.js</code> 组织筛选、阅读、矩阵与编辑界面，所有原文和生成内容均作为文本渲染。引用可打开原文定位窗口。</li></ol><p>先运行离线流程验证状态与引用链，再用固定输入测试模型适配。模型返回不符合结构或引文不匹配时任务失败，不静默替换成演示内容。</p></section><section id="workflow"><p class="eyebrow">04 / 操作顺序</p><h2>任务流程：一次完成可复查的综述</h2><ol><li>建立专题，填写研究问题、纳入/排除标准；导入两篇你有权使用的文献。</li><li>在“文献筛选”逐篇记录理由。打开原文核对文本提取质量，尤其是表格、公式与页码。</li><li>在“证据矩阵”建立阅读任务或手工摘录。编辑类别与说明，逐条比较原文，记录核对人和依据。</li><li>确认提纲后进入“章节草案”。模型模式会先提示最大调用次数；离线编排只产生待解释的摘编。</li><li>编辑章节，等待自动保存，提交新版本。引用可跳回被冻结的文献版本，不能把连续摘录等同于语义支持。</li><li>在“引用核对”选择确实读过的论述，记录通过或修改意见。全部通过后发布，下载 Markdown、BibTeX 和证据 JSON。</li></ol>${note('失败与来源变更','取消不撤销已经发出的模型请求。重试复用相同输入下成功的节点，不自动重试付费请求。更新原文后旧证据和草案会过期；先编辑或移除旧证据，再按当前版本重建。')}</section><section id="evaluation"><p class="eyebrow">05 / 可量化的验收</p><h2>成果评估：结构正确与综述质量分开测</h2>${table(['维度','评估方法','验收证据'],[['来源一致性','对照原文检查页码、字符位置、版本与输入范围','逐字匹配率、错误来源数、过期拦截记录'],['内容质量','研究者盲评覆盖度、可读性、归纳与冲突解释','评分表与分歧仲裁，不以模型自评分替代'],['模式对照','同一资料、提纲、供应商与重复次数，对比离线/单次/分工','质量、时延、实际供应商 token/费用；无记录则标缺失'],['工程稳定性','故障注入、并发编辑、重启、取消与失败节点重试','自动化测试、浏览器证据、持久化快照']])}<p>当前版本提供工程闭环，尚未完成跨领域研究者盲评，不能据此声称多智能体优于单次生成。正式课题可选择至少两个研究方向，先人工整理证据与参考综述，再做对照评估。</p></section><section id="boundary"><p class="eyebrow">06 / 使用与交付</p><h2>部署与能力边界</h2><p>与仓库其他项目共用运行环境。Docker：<code>docker compose up --build -d --wait --wait-timeout 90</code>。Conda 或 venv 的单指令启动见仓库 README；所有选题共用一套环境。服务端数据写入 <code>LAB_DATA_DIR/literature.sqlite3</code>。</p><p>使用 <code>python scripts/backup_process_data.py --project literature --output backups/literature.sqlite3</code> 创建一致性备份。恢复前停止服务，替换对应数据库并清理旧 WAL/SHM，再启动。</p><p>支持最多 100 份有效文献、单文件 8 MiB / 100 页 / 30 万字符、单专题 6 篇 / 60 条证据、提纲 1–4 章。模型阅读原文或写作证据输入超过 24000 字时拒绝，不做静默截断。暂不支持 OCR、外部学术搜索、参考文献自动消歧、账户权限或实时协作。</p>${link('settings','检查运行环境与数据 →','secondary btn')}</section></article></div>`;}
function settings(){return heading('数据与运行环境','当前工作区由本地服务保存，刷新页面或更换浏览器不会清空资料。')+`<div class="section-grid"><section class="panel"><h2>模型连接</h2>${badge(state.capabilities.llm?'confirmed':'pending',state.capabilities.llm?'已配置服务端模型':'未配置模型')}<p>离线流程可独立运行。若使用模型，在服务端设置 LAB_LLM_BASE_URL、LAB_LLM_MODEL、LAB_LLM_API_KEY，然后重启服务。</p>${note('按需发送','只有显式启动模型任务时，才向配置的供应商发送相应文献文本或证据。密钥不返回页面。')}<a href="../../docs/MODEL_SETUP.md">模型配置说明 →</a></section><section class="panel"><h2>数据持久化与备份</h2><p>文献版本、原文件、证据矩阵、任务节点、草案和发布记录保存在 literature.sqlite3。备份使用 SQLite backup API，不直接复制运行中的数据库文件。</p><p><code>python scripts/backup_process_data.py --project literature --output backups/literature.sqlite3</code></p><p class="muted">旧版浏览器摘记仍保留在原浏览器中；新版不将阅读摘记冒充论文原文自动迁移。</p>${link('guide?chapter=boundary','阅读部署与边界 →')}</section></div>`;}
async function render(){const n=++seq,hash=location.hash.slice(1)||'overview',[path,query='']=hash.split('?'),q=new URLSearchParams(query),[kind,id]=path.split('/'),view=$('#workspace-view');view.inert=true;$('#workspace-error').hidden=true;try{const next=await api('workspace');if(n!==seq)return;state=next;detail=null;evidence=[];let html;if(kind==='overview')html=overview();else if(kind==='library')html=library(q);else if(kind==='new')html=newProject();else if(kind==='import')html=importPage(q);else if(kind==='paper'){detail=await api('papers/'+id+(q.has('version')?'?version='+q.get('version'):''));html=paperView(detail,q);}else if(kind==='project'){detail=await api('projects/'+id);evidence=(await api('projects/'+id+'/evidence')).evidence;relations=(await api('projects/'+id+'/relations')).relations;projectAudit=await api('projects/'+id+'/audit');sourcePreview=null;const selectedEvidence=evidence.find(e=>e.id===q.get('evidence'));if(selectedEvidence)sourcePreview=await api('papers/'+selectedEvidence.paper+'?version='+selectedEvidence.version);html=projectView(detail,q);}else if(kind==='draft'){detail=await api('drafts/'+id+(q.has('version')?'?version='+q.get('version'):''));evidence=detail.context.evidence;html=draftView(detail,q);}else if(kind==='jobs')html=jobsView();else if(kind==='job'){detail=await api('jobs/'+id);html=jobView(detail);}else if(kind==='releases')html=releasesView();else if(kind==='guide')html=guide();else if(kind==='settings')html=settings();else html=empty('页面不存在','请返回研究工作台。',link('overview','返回工作台','btn'));if(n!==seq)return;view.innerHTML=html;view.dataset.route=hash;$('#download-local').hidden=kind!=='draft';const changed=route!==hash;route=hash;dirty=false;view.inert=false;document.title=(kind==='draft'?'章节编辑':kind==='project'?detail.title:'文献研读室')+' · D13';$$('[data-nav]').forEach(a=>{const match=a.dataset.nav===kind||a.dataset.nav==='library'&&['paper','import'].includes(kind)||a.dataset.nav==='projects'&&['project','new','draft'].includes(kind)||a.dataset.nav==='jobs'&&kind==='job';match?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});if(kind==='projects'){view.innerHTML=heading('研究专题','按研究问题组织文献、证据与章节。',link('new','建立专题','btn'))+projectRows(state.projects);}if(changed){view.focus({preventScroll:true});window.scrollTo(0,0);}if(kind==='guide'&&q.has('chapter'))document.getElementById(q.get('chapter'))?.scrollIntoView();if(kind==='paper'&&q.has('start'))$('#source-highlight')?.scrollIntoView({block:'center'});window.dispatchEvent(new CustomEvent('lab:render',{detail:{project:'D13',state,detail,route:hash,extra:{evidence,relations,audit:projectAudit}}}));}catch(err){if(n!==seq)return;view.inert=false;view.innerHTML=`<div class="inline-error"><h1>工作区暂未能读取</h1><p>${h(err.message)}</p><button id="refresh">重新读取</button></div>`;error(err.message);}}
function openDialog(title,html){$('#action-title').textContent=title;$('#action-content').innerHTML=html;if(document.body.classList.contains('guided-tour-active'))$('#action-dialog').show();else $('#action-dialog').showModal();}
function formFinish(){return '<p class="form-message" role="status"></p>';}
async function showEvidenceForm(e=null,initial={}){const p=route.startsWith('project/')?detail:project(initial.project),docs=state.papers.filter(d=>selection(p,d.id)?.decision==='included'&&d.current);if(!docs.length)throw Error('请先纳入可阅读文献。');const target=docs.find(d=>d.id===(e?.paper||initial.paper))||docs[0];openDialog(e?'编辑证据':'摘录证据',`<form id="evidence-form" data-id="${h(e?.id||'')}" data-project="${h(p.id)}" data-revision="${e?.revision||0}"><label>来源文献<select name="paper" aria-label="来源文献">${docs.map(d=>`<option value="${h(d.id)}" ${d.id===target.id?'selected':''}>${h(d.title)} · 当前 v${d.current}</option>`).join('')}</select></label><div class="form-grid"><label>证据类别<select name="field" aria-label="证据类别">${['method','finding','limitation'].map(f=>`<option value="${f}" ${e?.field===f?'selected':''}>${name(f)}</option>`).join('')}</select></label>${field('页码','page',e?.page||initial.page||1,'required type="number" min="1" max="100"')}</div>${area('逐字摘录（必须连续匹配原文）','quote',e?.quote||initial.quote||'','required maxlength="1500"')}${field('起始字符位置（0 起；留空则匹配唯一位置）','start',e?.start??initial.start??'','type="number" min="0"')}${area('证据说明与适用条件','summary',e?.summary||'','required maxlength="2000"')}<button type="submit">保存待核对证据</button>${formFinish()}</form>`);}
async function cite(id){const e=evidence.find(e=>e.id===id);if(!e)throw Error('引用证据不存在。');const doc=await api('papers/'+e.paper+'?version='+e.version),page=doc.version.pages.find(p=>p.page===e.page);openDialog('引用对照 · '+doc.version.metadata.title,`<div class="actions">${badge(doc.version.metadata.scope)}<span class="muted">v${e.version} / 第 ${e.page} 页 / 字符 ${e.start}–${e.end}</span></div><p class="muted">证据说明：${h(e.summary)}</p><div class="source-dialog">${pageText(page,e)}</div><p>${link('paper/'+e.paper+'?version='+e.version+'&page='+e.page+'&start='+e.start+'&end='+e.end,'在阅读区打开 →')}</p>${note('请判断支持关系','逐字匹配仅确认引文位置。是否支持论述、是否遗漏条件或混淆因果，需要阅读上下文。')}`);setTimeout(()=>$('#action-dialog #source-highlight')?.scrollIntoView({block:'center'}),30);}
function collectDraft(){const section=draftLocal.find(s=>s.claims.some(c=>$('#draft-form [data-claim-text="'+c.id+'"]')));if(section)for(const c of section.claims){const input=$('[data-claim-text="'+c.id+'"]'),select=$('[data-claim-evidence="'+c.id+'"]');if(input)c.text=input.value;if(select)c.evidence_ids=[...select.selectedOptions].map(o=>o.value);}return draftLocal;}
async function saveDraft(){clearTimeout(saveTimer);if(!dirty)return;const d=detail,revision=d.draft_revision,sections=structuredClone(collectDraft()),serial=JSON.stringify(sections);saving=true;$('#save-state').textContent='正在保存草稿…';try{const result=await api('drafts/'+d.id+'/save',{base_version:d.current,draft_revision:revision,sections});d.draft_revision=result.draft_revision;d.draft=sections;dirty=JSON.stringify(collectDraft())!==serial;$('#save-state').textContent=dirty?'有新修改，等待保存':'已保存草稿，尚未提交版本';if(dirty)scheduleSave();}catch(err){$('#save-state').textContent='未保存：'+err.message;error(err.message);throw err;}finally{saving=false;}}
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{autoPromise=autoPromise.catch(()=>{}).then(saveDraft);autoPromise.catch(()=>{});},1000);}
async function navigate(next){if(next===route)return;if(route.startsWith('draft/')&&dirty){try{await autoPromise;await saveDraft();}catch{if(!confirm('草稿未能保存。先下载本地文本，或确认放弃当前页面修改？'))return;}}else if(dirty&&!confirm('当前表单尚未保存，离开此页面？'))return;$('#action-dialog').close();location.hash=next;}
function localExport(){const url=URL.createObjectURL(new Blob([JSON.stringify(collectDraft(),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='d13-local-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('input',e=>{if(e.target.closest('#draft-form')){dirty=true;$('#save-state').textContent='有修改，等待自动保存';scheduleSave();}else if(e.target.closest('#workspace-view form'))dirty=true;});
document.addEventListener('change',e=>{if(e.target.id==='reader-project'){const q=new URLSearchParams(location.hash.split('?')[1]||'');q.set('project',e.target.value);navigate('paper/'+detail.paper.id+'?'+q);return;}if(e.target.id==='paper-version'){const q=new URLSearchParams(location.hash.split('?')[1]||'');q.set('version',e.target.value);q.delete('start');q.delete('end');navigate('paper/'+detail.paper.id+'?'+q);return;}if(e.target.id==='draft-version'){const q=new URLSearchParams(location.hash.split('?')[1]||'');q.set('version',e.target.value);navigate('draft/'+detail.id+'?'+q);return;}if(e.target.matches('[data-claim-evidence]')){dirty=true;scheduleSave();}});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.matches('#project-form,#import-form,#filter-form,#screen-form,#evidence-form,#evidence-review-form,#draft-form,#claim-review-form,#publish-form,#evidence-filter,#relation-form,form[data-generate]'))return;event.preventDefault();const button=form.querySelector('[type=submit]'),msg=form.querySelector('.form-message');if(button)button.disabled=true;if(msg)msg.textContent='';try{const v=new FormData(form),body=Object.fromEntries(v);if(form.id==='evidence-filter'){await navigate(projectLink(detail,'matrix',Object.fromEntries(v)));return;}if(form.id==='relation-form'){const es=Object.fromEntries(evidence.map(e=>[e.id,e]));body.revision=Number(form.dataset.revision);body.source_revisions={[body.left]:es[body.left].revision,[body.right]:es[body.right].revision};await api('projects/'+detail.id+'/relations'+(form.dataset.id?'/'+form.dataset.id:''),body);$('#action-dialog').close();toast('证据关系已保存，旧草案需重新检查');await render();return;}if(form.id==='filter-form'){dirty=false;location.hash='library?q='+encodeURIComponent(body.q);return;}if(form.id==='project-form'){body.outline=body.outline.split('\n').map(s=>s.trim()).filter(Boolean);body.outline_confirmed=v.has('outline_confirmed');if(form.dataset.id)body.revision=detail.revision;const r=await api('projects'+(form.dataset.id?'/'+form.dataset.id:''),body);dirty=false;toast('专题与提纲已保存');if(form.dataset.id)await render();else location.hash='project/'+r.project_id;}
else if(form.id==='import-form'){const f=v.get('file');delete body.file;if(f?.size){if(f.size>8*1024*1024)throw Error('文件超过 8 MiB。');const raw=new Uint8Array(await f.arrayBuffer());let str='';for(let i=0;i<raw.length;i+=16384)str+=String.fromCharCode(...raw.subarray(i,i+16384));body.content_base64=btoa(str);body.filename=f.name;}else body.filename='pasted.txt';if(form.dataset.paper){body.paper_id=form.dataset.paper;body.base_version=paper(form.dataset.paper).current;}const r=await api('papers',body);dirty=false;location.hash=r.job_id?'job/'+r.job_id:'paper/'+r.paper_id;}
else if(form.id==='screen-form'){const s=selection(detail,form.dataset.paper);await api('projects/'+detail.id+'/screen/'+form.dataset.paper,{...body,revision:s?.revision||0});$('#action-dialog').close();toast('筛选记录已保存');await render();}
else if(form.id==='evidence-form'){body.page=Number(body.page);if(body.start==='')delete body.start;else body.start=Number(body.start);body.version=paper(body.paper).current;body.revision=Number(form.dataset.revision);await api('projects/'+form.dataset.project+'/evidence'+(form.dataset.id?'/'+form.dataset.id:''),body);$('#action-dialog').close();toast('证据已保存，等待核对');await render();}
else if(form.id==='evidence-review-form'){const e=evidence.find(e=>e.id===form.dataset.id);await api('evidence/'+e.id+'/review',{...body,revision:e.revision});$('#action-dialog').close();toast('证据核对已记录');await render();}
else if(form.dataset.generate){if(body.mode!=='offline'){const count=body.mode==='single'?1:form.dataset.generate==='read'?detail.selections.filter(s=>s.decision==='included').length:detail.outline.length;if(!confirm(`本任务最多调用 ${count} 次模型 API，向配置的供应商发送${form.dataset.generate==='read'?'纳入文献文本':'已核对证据'}，可能产生费用。是否继续？`))return;}const r=await api('projects/'+detail.id+'/'+form.dataset.generate,body);dirty=false;location.hash='job/'+r.job_id;}
else if(form.id==='draft-form'){await autoPromise;await saveDraft();toast('草稿已保存');}
else if(form.id==='claim-review-form'){body.claim_ids=v.getAll('claim_ids');body.confirmed_count=body.claim_ids.length;body.version=detail.version;await api('drafts/'+detail.id+'/reviews',body);dirty=false;toast('所选论述核对已记录');await render();}
else if(form.id==='publish-form'){const r=await api('drafts/'+detail.id+'/publish',{...body,version:detail.version});$('#action-dialog').close();toast('审核快照已发布：'+r.release_id);location.hash='releases';}
}catch(err){if(msg)msg.textContent=err.message;else error(err.message);}finally{if(button)button.disabled=false;}});
document.addEventListener('click',async event=>{const a=event.target.closest('a[href^="#"]');if(a){if(event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||event.button>0)return;event.preventDefault();if(a.classList.contains('skip-link')){$('#workspace-view').focus();return;}await navigate(a.getAttribute('href').slice(1));return;}const b=event.target.closest('button');if(!b)return;try{if(b.dataset.close){$('#'+b.dataset.close).close();return;}if(b.id==='refresh'){if(dirty&&!confirm('刷新会放弃当前未保存表单内容，继续？'))return;await render();return;}if(b.id==='download-local'){localExport();return;}if(b.id==='archive-paper'){if(confirm('移出当前文献库？历史原文仍保留，相关证据与草案会过期。')){await api('papers/'+detail.paper.id+'/delete',{version:detail.paper.current});location.hash='library';}return;}if(b.id==='fill-sample'){const f=$('#import-form');f.elements.title.value='教学材料：来源冲突与证据核对（虚构）';f.elements.authors.value='课程示例';f.elements.year.value='2026';f.elements.scope.value='notes';f.elements.text.value='本教学材料使用两种检索策略比较来源冲突的呈现方式。\n示例一保留检索片段的出处，并由阅读者检查上下文。\n这一材料没有开展真实实验，不能用于证明任何方法的性能。';dirty=true;toast('已填入虚构教学文本，请按阅读摘记导入。');return;}if(b.dataset.screen){const s=selection(detail,b.dataset.screen);openDialog('记录文献筛选',`<form id="screen-form" data-paper="${h(b.dataset.screen)}"><p>${h(paper(b.dataset.screen).title)}</p><label>筛选结论<select name="decision" aria-label="筛选结论">${['included','excluded','undecided'].map(k=>`<option value="${k}" ${s?.decision===k?'selected':''}>${name(k)}</option>`).join('')}</select></label>${area('筛选理由','reason',s?.reason||'','required maxlength="1500"')}<button type="submit">保存筛选结论</button>${formFinish()}</form>`);return;}if(b.id==='new-relation'){showRelationForm();return;}if(b.dataset.editRelation){showRelationForm(b.dataset.editRelation);return;}if(b.dataset.deleteRelation){const r=relations.find(r=>r.id===b.dataset.deleteRelation);if(confirm('移除此关系？旧草案保留固定快照。')){await api('projects/'+detail.id+'/relations/'+r.id+'/delete',{revision:r.revision});await render();}return;}if(b.id==='add-evidence'){await showEvidenceForm();return;}if(b.dataset.editEvidence){await showEvidenceForm(evidence.find(e=>e.id===b.dataset.editEvidence));return;}if(b.dataset.reviewEvidence){const e=evidence.find(e=>e.id===b.dataset.reviewEvidence);openDialog('核对证据',`<form id="evidence-review-form" data-id="${h(e.id)}"><blockquote>${h(e.quote)}</blockquote><p>${h(e.summary)}</p><button type="button" class="text-button" data-view-original="${h(e.id)}">在新阅读页查看原文 ↗</button>${field('核对人','actor','','required maxlength="80"')}<label>核对结论<select name="status" aria-label="核对结论"><option value="confirmed">已核对：引文、类别与说明一致</option><option value="conflict">存在分歧：需修改或移除</option></select></label>${area('核对依据','comment','','required maxlength="2000"')}<button type="submit">记录证据核对</button>${formFinish()}</form>`);return;}if(b.dataset.viewOriginal){const e=evidence.find(e=>e.id===b.dataset.viewOriginal);window.open('#paper/'+e.paper+'?version='+e.version+'&page='+e.page+'&start='+e.start+'&end='+e.end,'_blank','noopener');return;}if(b.dataset.deleteEvidence){const e=evidence.find(e=>e.id===b.dataset.deleteEvidence);if(confirm('从当前矩阵移除此证据？已有草案保留快照并标记来源变化。')){await api('evidence/'+e.id+'/delete',{revision:e.revision});await render();}return;}if(b.id==='quote-selection'){const sel=window.getSelection(),source=$('.source-text');let quote='',start='';if(sel&&sel.rangeCount&&source.contains(sel.anchorNode)&&source.contains(sel.focusNode)){quote=sel.toString().trim();const r=document.createRange();r.selectNodeContents(source);r.setEnd(sel.getRangeAt(0).startContainer,sel.getRangeAt(0).startOffset);const before=r.toString(),leading=sel.toString().length-sel.toString().trimStart().length;start=Array.from(before).length+Array.from(sel.toString().slice(0,leading)).length;}if(Number(b.dataset.version)!==detail.paper.current)throw Error('历史版本只读，请在当前版本建立新证据。');await showEvidenceForm(null,{project:b.dataset.project,paper:b.dataset.paper,page:Number(b.dataset.page),quote,start});return;}if(b.dataset.cite){await cite(b.dataset.cite);return;}if(b.dataset.jobAction){b.disabled=true;try{if(b.dataset.jobAction==='retry'&&detail.mode!=='offline'&&!confirm('重试会继续未完成的模型节点，可能产生费用。成功节点在相同输入下复用。继续？'))return;const r=await api('jobs/'+detail.id+'/'+b.dataset.jobAction,{});if(r.job_id===detail.id)await render();else location.hash='job/'+r.job_id;}finally{b.disabled=false;}return;}if(b.id==='commit-draft'){await autoPromise;await saveDraft();if(!detail.draft)throw Error('没有需要提交的草稿。');const r=await api('drafts/'+detail.id+'/commit',{base_version:detail.current,draft_revision:detail.draft_revision});dirty=false;toast('已提交 v'+r.version+'，请重新核对引用');const q=new URLSearchParams(location.hash.split('?')[1]||'');q.set('version',r.version);location.hash='draft/'+detail.id+'?'+q;return;}if(b.id==='discard-draft'){if(confirm('放弃已保存草稿，回到已提交版本？')){await api('drafts/'+detail.id+'/discard',{base_version:detail.current,draft_revision:detail.draft_revision});dirty=false;await render();}return;}if(b.id==='select-claims'){$$('#claim-review-form [name=claim_ids]:not(:disabled)').forEach(c=>c.checked=true);return;}if(b.id==='publish-draft'){openDialog('发布审核快照',`<form id="publish-form"><p>固定当前章节、来源和核对记录。后续修改不覆盖此快照。</p>${field('发布记录人','actor','','required maxlength="80"')}<button type="submit">确认发布审核快照</button>${formFinish()}</form>`);return;}if(b.id==='topic-open'){const t=window.ProjectTopics?.literature;$('#topic-content').innerHTML=`<p class="eyebrow">丁箐 · D13 / 选题说明</p><h2 id="topic-title">基于多智能体协同的科研文献智能综述生成系统</h2><h3>研究目标</h3><p>${h(t?.core||'围绕研究问题，协同完成文献阅读、证据整理与综述写作。')}</p><h3>当前实现</h3><p>真实文件导入、文献版本、筛选理由、逐字定位证据矩阵、阅读与写作节点、章节草稿、人工引用核对、文献对照、证据关系、写作前检查和不可变发布快照。单次模型与分工模式均需显式配置。</p><h3>建议的评估</h3><p>固定文献与问题，对比单次生成与分工协作的覆盖度、引用支持率、可读性、时延和实际费用。用研究者盲评判断内容质量。</p><h3>难点与边界</h3><p>引用存在不代表语义成立。来源冲突、研究条件差异与信息缺失需要人工判断。当前未完成跨领域盲评，不宣称多智能体质量更高。</p><p>难度 ${h(t?.difficulty||4)} / 5 · 简历价值 ${h(t?.value||4)} / 5。评分是选题分析，不代表完成度。</p>`;$('#topic-dialog').showModal();}}
catch(err){error(err.message);}});
window.addEventListener('hashchange',()=>{clearTimeout(saveTimer);render();});window.addEventListener('beforeunload',event=>{if(dirty||saving){event.preventDefault();event.returnValue='';}});
const nav=[['overview','研究工作台','home'],['projects','研究专题','layers'],['library','文献库','book'],['jobs','任务记录','list'],['releases','发布快照','publish'],['guide','项目指南','checklist'],['settings','数据与环境','settings']];
document.body.innerHTML=`<a href="#workspace-view" class="skip-link">跳到正文</a><aside class="rail"><a class="brand" href="#overview">${icon('book')}<div>文献研读室<small>RESEARCH WORKSPACE / D13</small></div></a><div class="rail-label">研究空间</div><nav aria-label="主导航">${nav.map(([r,l,i])=>`<a data-nav="${r}" href="#${r}">${icon(i)}${l}</a>`).join('')}</nav><div class="rail-foot"><span>从文献到可复查的综述</span><a href="../../index.html">项目总览 ↗</a><a href="../../report/upgrade-plan.html">参考调研与完善计划</a></div></aside><div class="surface"><header class="topbar"><span><strong>文献研读室</strong><i>/</i><span class="only-desktop">证据与写作</span></span><div><span class="only-desktop">本地研究空间</span><button id="topic-open" class="secondary small" aria-haspopup="dialog" aria-controls="topic-dialog">${icon('info')}选题介绍</button></div></header><main id="workspace-view" tabindex="-1"><p>正在读取文献工作区…</p></main></div><div id="workspace-error" class="workspace-error" role="alert" hidden><span id="error-message"></span><div class="actions"><button id="download-local" class="secondary small">下载本地章节</button><button id="refresh" class="secondary small">重新读取</button></div></div><div id="toast" class="toast" role="status" hidden></div><dialog id="action-dialog" aria-labelledby="action-title"><div class="dialog-heading"><h2 id="action-title"></h2><button class="secondary small" data-close="action-dialog" aria-label="关闭窗口">关闭</button></div><div id="action-content"></div></dialog><dialog id="topic-dialog" aria-labelledby="topic-title"><div id="topic-content"><h2 id="topic-title">选题介绍</h2></div><button class="secondary" data-close="topic-dialog">关闭</button></dialog>`;
$('#action-dialog').addEventListener('close',()=>$('#action-content').replaceChildren());
render();setInterval(async()=>{if(polling||dirty||saving||document.hidden||$('dialog[open]')||!state)return;if(!['overview','jobs','job','library'].includes(route.split(/[/?]/)[0]))return;polling=true;try{const next=await api('workspace');if(JSON.stringify(next.jobs)!==JSON.stringify(state.jobs))await render();}catch{}finally{polling=false;}},1500);
})();
